        bp = b.get(proj, {})
        ap = a.get(proj, {})
        for pkg in set(list(bp.keys()) + list(ap.keys())):
            if bp.get(pkg) != ap.get(pkg):
                print(f'  {proj}: {pkg} {bp.get(pkg)} -> {ap.get(pkg)}')
"

